        }
      ],
      "line": "p4:L4"
    },
    {
      "after_item": "S5_SPECIFIC",
      "title_raw": "○ 열분해성 생성물",
      "reason": "코드없음",
      "statements": [
        {
          "key": "열분해성 생성물",
          "value": "고온에서 분해되어 독성가스를 생성할 수 있음."
        ,
          "line": "p4:L8"
        },
        {
          "key": "열분해성 생성물",
          "value": "타는 동안 열분해 또는 연소에 의해 자극적이고 매우 유독한 가스가 발생될 수 있음."
        ,
          "line": "p4:L9"
        }
      ],
      "line": "p4:L7"
    },
    {
      "after_item": "S5_SPECIFIC",
      "title_raw": "○ 화재 및 폭발 위험",
      "reason": "코드없음",
      "statements": [
        {
          "key": "화재 및 폭발 위험",
          "value": "격렬하게 중합반응하여 화재와 폭발을 일으킬 수 있음."
        ,
          "line": "p4:L11"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "가열시 용기가 폭발할 수 있음."
        ,
          "line": "p4:L12"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "가열시 증기는 공기와 혼합하여 폭발성 혼합물을 형성할 수 있음; 실내, 실외, 하수구에 폭발 위험."
        ,
          "line": "p4:L13"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "공기와 폭발성 혼합물을 형성함."
        ,
          "line": "p4:L14"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "극인화성."
        ,
          "line": "p4:L15"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "열, 스파크, 화염에 의해 쉽게 점화함."
        ,
          "line": "p4:L16"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "일부는 탈 수 있으나 급격하게 연소하지 않음"
        ,
          "line": "p4:L17"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "증기는 점화원까지 이동하여 역화(flash back)할 수 있음."
        ,
          "line": "p4:L18"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "화재에 노출된 실린더는 가연성 가스를 방출할 수 있음."
        ,
          "line": "p4:L19"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "실레인(실리콘 수소화물)은 공기 중에서 자연점화함."
        ,
          "line": "p4:L20"
        }
      ],
      "line": "p4:L10"
    },
    {
      "after_item": "S5_SPECIFIC",
      "title_raw": "○ 기타",
      "reason": "코드없음",
      "statements": [
        {
          "key": "기타",
          "value": "화재에 노출된 실린더는 가연성 가스를 방출할 수 있음."
        ,
          "line": "p4:L22"
        },
        {
          "key": "기타",
          "value": "일부 물질은 고농도로 흡입시 자극적일 수 있음."
        ,
          "line": "p4:L23"
        },
        {
          "key": "기타",
          "value": "증기는 자각 없이 현기증 또는 질식을 유발할 수 있음."
        ,
          "line": "p4:L24"
        },
        {
          "key": "기타",
          "value": "화재시 자극성, 부식성, 독성 가스를 발생할 수 있음."
        ,
          "line": "p4:L25"
        }
      ],
      "line": "p4:L21"
    }
  ]
}

